SELECT * FROM direct_conversations
WHERE project_id = #{projectId}
  AND (
    (participant_a_type = 'USER' AND participant_a_id = #{userId})
    OR (participant_b_type = 'USER' AND participant_b_id = #{userId})
  )

SELECT COUNT(*) FROM direct_conversations
WHERE group_id = #{groupId}
  AND participant_b_type = 'AGENT' AND participant_b_id = #{agentId}
